+	struct clk		*xo_clk;
+	struct icc_path		*icc_path;
+	spinlock_t		lock; /* protects rx_count, rx_msg_buf, tx_count, tx_msg_buf */
+	u16			slave_addr;
+	u8			rx_count;
+	u8			rx_msg_buf[I2C_SLAVE_MAX_MSG_SIZE];
+	u8			tx_count;
+	u8			tx_msg_buf[I2C_SLAVE_MAX_MSG_SIZE];
